-- The SIE (Health Skills Immersive Experience) feedback template: same question format as the HealthX form, with the SIE's
-- own wording and completion options. Question ids are field keys from the dictionary.

insert into public.feedback_template (intervention_id, title, questions)
select i.id, 'SIE feedback', $json$[{"id": "completed", "label": "Did you complete the full SIE programme (both virtual and in-person phases)?", "type": "single", "required": true, "options": ["Yes, both phases", "Virtual phase only", "In-person phase only"]}, {"id": "relevance", "label": "How relevant was the SIE to your health mission and career goals?", "type": "single", "required": true, "options": ["Not relevant at all", "Somewhat relevant", "Moderately relevant", "Very relevant", "Extremely relevant"]}, {"id": "quality", "label": "How would you rate the quality of the SIE (content, facilitation, learning experiences)?", "type": "single", "required": true, "options": ["Poor quality", "Below average", "Average/Acceptable", "Good quality", "Excellent quality"]}, {"id": "usefulness", "label": "How useful was the SIE in helping you apply your skills to real-world health system contexts and understand employment pathways?", "type": "single", "required": false, "options": ["Not useful at all", "Somewhat useful", "Moderately useful", "Very useful", "Extremely useful - I have clear next steps"]}, {"id": "confidence", "label": "After the SIE, how confident are you in your ability to apply your skills [technology/entrepreneurship/leadership] to solve real-world health challenges?", "type": "single", "required": false, "options": ["Not confident at all", "Slightly confident", "Moderately confident", "Very confident", "Extremely confident"]}, {"id": "gains", "label": "Which of the following did you gain from this experience? (Select all that apply)", "type": "multi", "required": false, "options": ["Understanding of health system functioning in Africa", "Exposure to diverse health sector employment pathways", "Practical skills to apply in health contexts", "Networking with health professionals and organizations", "Clarity on my career direction in health", "Confidence in my health mission", "Other, please specify"]}, {"id": "next_action", "label": "What specific action will you take next based on what you learned? (e.g. pursue a health sector internship, launch a health venture, apply for a health role, continue health mission work, seek mentorship)", "type": "long", "required": false}, {"id": "support_needed", "label": "What support do you need to move forward?", "type": "multi", "required": false, "options": ["Mentorship", "Funding", "Job placement support", "Peer network", "Further training", "Other"]}, {"id": "nps", "label": "Would you recommend the SIE to other health mission students on a scale of 0-10? (0 = Not at all likely, 10 = Extremely likely)", "type": "scale10", "required": true}, {"id": "most_valuable", "label": "What was most valuable about this experience?", "type": "long", "required": false}, {"id": "improvements", "label": "What could be improved for future editions?", "type": "long", "required": false}]$json$::jsonb
from public.interventions i where i.name = 'SIE' and i.pillar = 'HEMP';
